import time
import Adafruit_ADS1x15
import board
import busio

# Constants for the ADS1115 configuration
GAIN = 1  # Gain setting for the ADC
RANGE = 4.096  # Voltage range of the ADC

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_adc(i2c_bus):
    """Initializes the ADS1115 ADC."""
    try:
        return Adafruit_ADS1x15.ADS1115(i2c_bus)
    except Exception as e:
        print(f"Error initializing ADC: {e}")
        return None

def read_adc_channels(adc_instance):
    """Reads all four channels from the ADC."""
    try:
        return [adc_instance.read_adc(channel, gain=GAIN, range=RANGE) for channel in range(4)]
    except Exception as e:
        print(f"Error reading ADC channel: {e}")
        return None

def format_adc_values(values):
    """Formats the ADC values into a list of strings."""
    if values is None or len(values) != 4:
        return None
    return ['0x{:04X}'.format(value) for value in values]

def print_header():
    """Prints the header row for the output table."""
    print('Channel A0 A1 A2 A3')
    print('-' * 37)

def main():
    """Main function to read and print ADC values."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return  # Exit if I2C initialization failed

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return  # Exit if ADC initialization failed

    try:
        while True:
            values = read_adc_channels(adc)
            if values:
                formatted_values = format_adc_values(values)
                if formatted_values:
                    print_header()
                    print(formatted_values)
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        # No specific cleanup needed for Adafruit_ADS1x15, but including a placeholder
        print("Cleanup complete.")

if __name__ == "__main__":
    main()

