import time
import cv2
from pyzbar.pyzbar import decode
from picamera2 import Picamera2

def initialize_camera():
    """Initializes the Raspberry Pi camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (64, 64)}))
        camera.start()
        time.sleep(1)  # Allow camera to warm up
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(camera):
    """Captures a single frame from the camera."""
    try:
        return camera.capture_array()
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in a frame."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = decode(gray)
        return decoded_objects
    except Exception as e:
        print(f"Error decoding QR code: {e}")
        return None

def main():
    """Main function to capture and decode QR codes."""
    camera = initialize_camera()
    if camera is None:
        return

    try:
        frame = capture_frame(camera)
        if frame is None:
            return

        decoded_objects = decode_qr_code(frame)

        if decoded_objects:
            print("Hello, World!")
            # Add code here to perform actions based on the decoded data
            # For example: print the decoded data, send it to a database, etc.
        else:
            print("No QR code detected.")

    finally:
        camera.stop()
        camera.close()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

