import cv2
import numpy as np
import logging
import time

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def mse(image_a, image_b):
    """Calculates the Mean Squared Error between two images."""
    err = np.sum((image_a.astype("float") - image_b.astype("float")) ** 2)
    err /= float(image_a.shape[0] * image_a.shape[1])
    return err

def lighting_compensation(frame):
    """Applies CLAHE for lighting compensation."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return cv2.equalizeHist(gray)

def apply_blur(frame):
    """Applies a Gaussian blur."""
    return cv2.GaussianBlur(frame, (3, 3), 0)

def detect_motion(previous_frame, current_frame):
    """Detects motion by comparing two frames using MSE."""
    if previous_frame is None:
        return False
    return mse(previous_frame, current_frame) > 100.0

def process_frame(frame, previous_frame):
    """Processes a single frame: applies lighting compensation, blur, and detects motion."""
    compensated_frame = lighting_compensation(frame)
    blurred_frame = apply_blur(compensated_frame)
    current_frame = cv2.cvtColor(blurred_frame, cv2.COLOR_BGR2GRAY)
    return current_frame, detect_motion(previous_frame, current_frame)

def main():
    """Main function to capture and process video frames."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            logging.error("Could not open camera.")
            return

        while True:
            ret, frame = cap.read()
            if not ret:
                logging.error("Could not read frame.")
                break

            current_frame, motion_detected = process_frame(frame, None)

            if motion_detected:
                logging.info("Motion Detected using MSE!")

            cv2.imshow('Original', frame)
            cv2.imshow('Compensated', compensated_frame)
            cv2.imshow('Grayscale', current_frame)
            cv2.imshow('Edges', cv2.Canny(current_frame, 50, 150))

            if cv2.waitKey(1) & 0xFF == 27:  # ESC key
                break

    except Exception as e:
        logging.exception(f"An error occurred: {e}")
    finally:
        if 'cap' in locals() and cap.isOpened():
            cap.release()
        cv2.destroyAllWindows()

if __name__ == "__main__":
    main()

