import cv2
import time
import os

def initialize_camera(camera_index=0, max_attempts=3):
    """Initializes the camera with error handling and retries."""
    for attempt in range(max_attempts):
        try:
            cap = cv2.VideoCapture(camera_index)
            if cap.isOpened():
                return cap
            else:
                print(f"Error: Could not open camera at attempt {attempt + 1}")
        except Exception as e:
            print(f"Error initializing camera: {e}")
    print("Error: Could not initialize camera after multiple attempts.")
    return None

def detect_faces(frame, face_cascade):
    """Detects faces in a frame using the provided Haar cascade classifier."""
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    return face_cascade.detectMultiScale(gray, 1.3, 5)

def draw_bounding_box(frame, x, y, w, h, color):
    """Draws a bounding box around detected faces in the frame."""
    cv2.rectangle(frame, (x, y), (x + w, y + h), color, 2)

def capture_and_save_image(cap, name, image_dir="images"):
    """Captures an image, saves it to the specified directory, and returns the path."""
    if not os.path.exists(image_dir):
        os.makedirs(image_dir)
    ret, frame = cap.read()
    filename = os.path.join(image_dir, name + "_" + str(time.time()) + ".jpg")
    cv2.imwrite(filename, frame)
    print(f"Image saved to {filename}")
    return filename

def main():
    """Main function to capture face images."""
    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + "haarcascade_frontalface_default.xml")
    cap = initialize_camera()
    if cap is None:
        return

    count = 0
    print("Waiting for face...")
    while count < 5:
        ret, frame = cap.read()
        if not ret:
            print("Error: Could not read frame.")
            break

        faces = detect_faces(frame, face_cascade)
        for (x, y, w, h) in faces:
            cv2.rectangle(frame, (x, y), (x + w, y + h), (255, 0, 0), 2)
            name = input("Enter person's name: ")
            capture_and_save_image(cap, name)
            count += 1
            print(count)
            cv2.imshow("Face", frame)

        if cv2.waitKey(1) & 0xFF == ord('q'):
            break

    cv2.destroyAllWindows()
    cap.release()

if __name__ == "__main__":
    main()

