            self(ws, self.path).upgrade_to_websockets()
            self.broadcast_loop()
        except Exception as e:
            logging.error(f"Error handling WebSocket request: {e}")
            self.send_response(504)  # Gateway Timeout
            self.send_header('Content-Type', 'text/plain')
            self.end_headers()
            self.wfile.write(b'WebSocket connection failed')
            self.close_connection()

    def broadcast_loop(self) -> None:
        """Continuously broadcasts messages to connected clients."""
        connected_clients = self.has_connections()
        if not connected_clients:
            logging.debug("No connected clients. Skipping broadcast.")
            return

        try:
            while True:
                if connected_clients.wait(0.1): # Check for new connections every 100ms
                    self.broadcast_function(np.array_to_bytes(self.frame))
                self.ws.send("Broadcasting...") # Send heartbeat
                time.sleep(1) # Adjust sleep as needed
        except Exception as e:
            logging.error(f"Error in broadcast loop: {e}")
            self.close_connection()

    def has_connections(self) -> bool:
        """Checks if there are any active WebSocket connections."""
        return bool(self.ws)

    def close_connection(self) -> None:
        """Closes a single WebSocket connection."""
        try:
            self.ws.close()
            logging.info(f"Client {self.ws.remote_ip} disconnected.")
        except Exception as e:
            logging.error(f"Error closing connection for {self.ws.remote_ip}: {e}")


def create_camera_stream(camera_config: dict = {}) -> Tuple[Picamera2, Optional[WebSocketHandler]]:
    """Creates and configures the Picamera2 camera stream.

    Args:
        camera_config: A dictionary of camera configuration parameters.

    Returns:
        A tuple containing the configured Picamera2 object and a WebSocketHandler.
        Returns only the Picamera2 object if configuration fails.
    """
    try:
        picam2 = Picamera2()
        picam2.configure(camera_config)
        picam2.start()
        logging.info("Camera stream started successfully.")
        return picam2, None
    except Exception as e:
        logging.error(f"Error initializing camera stream: {e}")
        return None, "Camera initialization failed"


def detect_motion(frame: bytes, prev_frame: bytes) -> Optional[bytes]:
    """Detects motion between two frames.

    Args:
        frame: The current frame as bytes.
        prev_frame: The previous frame as bytes.

    Returns:
        A byte array representing the motion detection result, or None if no motion is detected.
    """
    try:
        current_frame = np.frombuffer(frame, dtype=np.uint8)
        current_frame = cv2.imdecode(current_frame, cv2.IMREAD_GRAYSCALE)
        prev_frame = np.frombuffer(prev_frame, dtype=np.uint8)
        prev_frame = cv2.imdecode(prev_frame, cv2.IMREAD_GRAYSCALE)

        if current_frame is None or prev_frame is None:
            logging.error("Failed to decode frames for motion detection.")
            return None

        frame_diff = cv2.absdiff(current_frame, prev_frame)
        thresh = cv2.threshold(frame_diff, 25, 255, cv2.THRESH_BINARY)[1]
        thresh = cv2.dilate(thresh, None, iterations=2)
        cnts = cv2.findContours(thresh.copy(), cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)[0]

        if cnts:
            logging.info("Motion detected!")
            return frame
        else:
            return None
    except Exception as e:
        logging.error(f"Error during motion detection: {e}")
        return None


def send_frame(frame_data: bytes) -> None:
    """Sends a frame data to all connected clients.

    Args:
        frame_data: The frame data as bytes.
    """
    try:
        websocket_handlers[:]  # Clear existing handlers
        websocket_handlers = [
            WebSocketHandler(broadcast_frame_data)
            for _ in websocket_handlers
        ]

        if not websocket_handlers:
            logging.warning("No WebSocketHandler available to broadcast frame data.")
            return

        for handler in websocket_handlers:
            try:
                handler.ws.send(frame_data)
            except Exception as e:
                logging.error(f"Error sending frame data to client {handler.ws.remote_ip}: {e}")

    except Exception as e:
        logging.error(f"Error broadcasting frame data: {e}")


def broadcast_function(frame_data: bytes) -> None:
    """Broadcasts frame data to all connected clients using websockets."""
    send_frame(frame_data)


def camera_loop(picam2: Picamera2, frame_buffer: bytes, frame_lock: threading.Lock, broadcast_function: Callable[[bytes], None]) -> None:
    """Continuously captures frames from the camera and puts them in the buffer."""
    last_frame = time.time()

    while True:
        try:
            start_time = time.time()
            frame = picam2.capture_array()

            if frame is None:
                logging.error("Captured frame is empty.")
                time.sleep(0.1)  # Prevent busy-waiting
                continue

            with frame_lock:
                if frame_buffer == b"" or (time.time() - last_frame) > 0.1: # Add a small buffer
                    frame_buffer = b"".join([frame_buffer, frame])

            last_frame = time.time()
            time.sleep(0.01)  # Control loop frequency

        except Exception as e:
            logging.error(f"Error in camera loop: {e}")
            time.sleep(1)  # Wait before retrying


def main() -> None:
    """Main function to initialize and run the camera stream and WebSocket broadcast."""
    broadcast_function = broadcast_bytes # Example broadcast function
    picam2, websocket_handler = create_camera_stream()

    if not picam2:
        return

    frame_buffer = b""
    frame_lock = threading.Lock()

    # Start the camera and broadcast loops in separate threads
    camera_thread = threading.Thread(target=camera_loop, args=(picam2, frame_buffer, frame_lock, broadcast_function))
    broadcast_thread = threading.Thread(target=broadcast_function)

    camera_thread.start()
    broadcast_thread.start()

    try:
        HTTPServer(("0.0.0.0", 8765), WebSocketHandler, broadcast=broadcast_function).serve_forever()
    except KeyboardInterrupt:
        logging.info("Shutting down server...")
    except Exception as e:
        logging.error(f"Server error: {e}")
    finally:
        camera_thread.join()
        broadcast_thread.join()
        picam2.close()
        logging.info("Server stopped.")


def np_from_buffer(buffer: bytes) -> Optional[np.ndarray]:
    """Converts a byte buffer to a NumPy array."""
    try:
        np_array = np.frombuffer(buffer, dtype=np.uint8)
        return np_array
    except Exception as e:
        logging.error(f"Error converting buffer to NumPy array: {e}")
        return None


def bytes_from_np_array(np_array: np.ndarray) -> bytes:
    """Converts a NumPy array to a byte buffer."""
    try:
        return np_array.tobytes()
    except Exception as e:
        logging.error(f"Error converting NumPy array to buffer: {e}")
        return b""


def broadcast_bytes(frame_data: bytes) -> None:
    """Broadcasts frame data by sending it to all connected WebSocket clients."""
    # Example: Send a simple message with the frame data
