def frame_to_string(frame_data: bytes) -> str:
    """Converts frame data to a string representation."""
    try:
        np_array = np_from_buffer(frame_data)
        if np_array is None:
            return "Error converting frame data to NumPy array."

        # Perform motion detection
        motion_result = detect_motion(np_array, b"")

        if motion_result is not None:
            return f"Motion Detected: {motion_result.decode()}"
        else:
            return f"No motion detected: {np_array.shape}"
    except Exception as e:
        logging.error(f"Error processing frame: {e}")
        return "Error processing frame."


