                                    #vhr { flex: 1; }
                                </style>
                                <div id='vhr'>
                                    <video autoplay loop></video>
                                </div>
                            </html>"""
        elif path == b'/ws':
            # Handle the WebSocket upgrade
            upgrade_to_websockets()
        elif path == b'/status':
            # Return the current status
            response_code = 200
            status_message = "OK"
            return self.send_response(response_code), [status_message]
        else:
            # Serve the HTML page
            self.send_response(200)
            self.send_header('Content-Type', 'text/html')
            self.end_headers()
            return self.wfile.write(html_content)

    except Exception as e:
