            # Send an initial frame to the client
            ws.send(b"Welcome to the motion detection stream!")

    except Exception as e:
        logging.error(f"Error handling WebSocket open: {e}")


def websocket_on_close(ws: websockets.Connection, path: str) -> None:
    """Handles a WebSocket connection closing."""
    try:
        if path == b'/ws':
            logging.info(f"WebSocket connection closed from {ws.remote_ip}")
    except Exception as e:
