def camera_loop(picam2: Picamera2, frame_buffer: bytes, frame_lock: threading.Lock, broadcast_function: Callable[[bytes], None]) -> None:
    """Continuously captures frames from the camera and puts them in the buffer."""
    last_frame = time.time()

    while True:
        try:
            start_time = time.time()
            frame = picam2.capture_array()

            if frame is None:
                logging.error("Captured frame is empty.")
                time.sleep(0.1)  # Prevent busy-waiting
                continue

            with frame_lock:
                if frame_buffer == b"" or (time.time() - last_frame) > 0.1: # Add a small buffer
                    frame_buffer = b"".join([frame_buffer, frame])

            last_frame = time.time()
            time.sleep(0.01)  # Control loop frequency

        except Exception as e:
