            logging.info(f"WebSocket connection closed from {ws.remote_ip}")
    except Exception as e:
        logging.error(f"Error handling WebSocket close: {e}")


def websocket_on_error(ws: websockets.Connection, path: str, exc_info: tuple) -> None:
    """Handles an error during WebSocket communication."""
    try:
        if path == b'/ws':
            logging.error(f"WebSocket error: {exc_info[1]}")
    except Exception as e:
        logging.error(f"Error handling WebSocket error: {e}")


def handle_client(client_socket: socket, client_address: tuple) -> None:
    """Handles an incoming client connection."""
    try:
        logging.info(f"Accepted connection from {client_address[1]}")
        http_request = client_socket.recv(1024)
        path, query_string = http_request.split()
        query_params = {}
        if there_is_a_query = "?" in path:
            first_part, second_part = path.split("?", 1)
            path = second_part
            query_params = parse_query(query_string)
        httpd.request_handler(handle_request, (path, query_params))
    except Exception as e:
        logging.error(f"Error handling client connection: {e}")
    finally:
        client_socket.close()


def parse_query(query_string: str) -> dict:
    """Parses a query string into a dictionary."""
    items = {}
    pairs = query_string.split("&")
    for pair in pairs:
        key, value = pair.split("=", 1)
        items[key] = value
    return items


def there_is_a_query(qs: str) -> bool:
    """Checks if a query string is present."""
    return "?" in qs


def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    logging.info(f"Received signal {sig}. Shutting down...")
    exit(0)


def main() -> None:
    """Main function to start the server."""
    socket_family = socket.AF_INET
    server_address = ('0.0.0.0', 8765)
    server_socket = socket.socket(socket_family, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)  # Allow address reuse
    server_socket.bind(server_address)
    server_socket.listen(5)
    logging.info(f"Server listening on {server_address}")

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    while True:
        try:
            client_socket, client_address = server_socket.accept()
            handle_client(client_socket, client_address)
        except OSError as e:
            logging.error(f"Accept error: {e}")
            time.sleep(1)
        except KeyboardInterrupt:
            logging.info("Shutting down server...")
            break
        except Exception as e:
            logging.error(f"Server error: {e}")
            time.sleep(1)


if __name__ == '__main__':
    main()

