    Attributes:
        driver (cv2.VideoCapture): The video capture driver.
        buffer (io.BytesIO): The in-memory buffer for the stream.
        complete_flag (bool): Flag indicating if a complete frame is available.
        encode_flags (int): The current encoding parameters.
    """

    def __init__(self, driver: cv2.VideoCapture):
        self.driver = driver
        self.buffer = io.BytesIO()
        self.complete_flag = False
        self.encode_flags = 0

    def write(self, d: bytes) -> None:
        """Writes data to the buffer and handles frame completion."""
        try:
            self.buffer.write(d)
            if self.driver.get(cv2.CAP_PROP_FRAME_COUNT) > 0:
                self.handle_frame()
        except Exception as e:
            logging.error(f"Error writing to buffer: {e}")

    def handle_frame(self) -> None:
        """Handles a complete frame, decodes it, and calls the callback."""
        if self.driver.get(cv2.CAP_PROP_FRAME_COUNT) > 0:
            try:
                frame_data = self.buffer.getvalue()
                self.buffer.seek(0)
                self.buffer.truncate()

                if self.decode_frame(frame_data):
                    self.complete_flag = True
            except Exception as e:
                logging.error(f"Error handling frame: {e}")

    def decode_frame(self, frame_data: bytes) -> bool:
        """Decodes a frame and returns True if successful."""
        try:
            self.driver.set(cv2.CAP_PROP_FRAME_COUNT, 0)
            self.driver.set(cv2.CAP_PROP_POS_FRAMES, 0)
            success, frame = self.driver.read()
            if success:
                self.encode_flags |= self.driver.get(cv2.CAP_PROP_FRAME_TYPE)
                return success
            else:
