import smbus
import time
import os

# Define the thermal zone file
ZONE_FILE = '/sys/class/thermal/thermal_zone0/temp'

# Initialize I2C bus
try:
    bus = smbus.SMBus(1)
except FileNotFoundError:
    print("Error: I2C bus not found. Please enable I2C.")
    exit()
except PermissionError:
    print("Error: Insufficient permissions to access I2C bus.")
    exit()

def read_temperature():
    """Reads the CPU temperature from the thermal zone file."""
    try:
        with open(ZONE_FILE, 'r') as f:
            temp_milli = f.read().strip()
            temp_celsius = float(temp_milli) / 1000.0
            return temp_celsius
    except FileNotFoundError:
        print("Error: Thermal zone file not found.")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def main():
    """Main function to read and display the temperature."""
    print("Starting temperature monitoring...")

    while True:
        temperature = read_temperature()
        if temperature is not None:
            print(f"CPU Temperature: {temperature:.2f} °C")
        time.sleep(2)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("Monitoring stopped by user.")
    finally:
        try:
            bus.close()  # Release the I2C bus
        except AttributeError:
            # bus might not have been initialized if I2C failed to start
            pass
        print("Exiting program.")

