import RPi.GPIO as GPIO
import socket
import json
import argparse
import time
import os

# Define GPIO pins (default values)
RELAY_PIN = 17
DHT_PIN = 4

# Default IP address for authorized connections
AUTHORIZED_IP = "192.168.1.100"

# Default log file path
LOG_FILE = "hydroponics_controller.log"

def setup_gpio(relay_pin, dht_pin):
    """Sets up the GPIO pins for the relay and DHT sensor."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(relay_pin, GPIO.OUT)
        GPIO.output(relay_pin, GPIO.LOW)  # Initialize relay to OFF
        print("GPIO setup complete.")
    except Exception as e:
        log_error(f"GPIO setup failed: {e}")
        raise

def read_temperature():
    """Reads the temperature from the DHT sensor (simulated)."""
    # Simulate DHT11 reading for demonstration purposes
    return 25.0  # Fixed temperature for this example

def control_pump(relay_pin, state):
    """Controls the water pump via the relay."""
    try:
        GPIO.output(relay_pin, GPIO.HIGH if state == "on" else GPIO.LOW)
        print(f"Pump {'ON' if state == 'on' else 'OFF'}")
    except Exception as e:
        log_error(f"Error controlling pump: {e}")

def get_status(relay_pin, temperature):
    """Returns the current pump state and temperature."""
    return {"pump_state": "on" if GPIO.input(relay_pin) else "off", "temperature": temperature}

def log_error(message):
    """Logs an error message to the log file."""
    timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} - ERROR: {message}\n"
    try:
        with open(LOG_FILE, "a") as f:
            f.write(log_entry)
    except Exception as e:
        print(f"Error writing to log file: {e}")

def handle_client(conn, addr, relay_pin, dht_pin, port, authorized_ip):
    """Handles a single client connection."""
    try:
        print(f"Connected by {addr}")
        while True:
            data = conn.recv(1024)
            if not data:
                break

            try:
                command = json.loads(data.decode())
                if command.get("command") == "pump_on":
                    control_pump(relay_pin, "on")
                    response = {"status": "success", "message": "Pump turned ON"}
                elif command.get("command") == "pump_off":
                    control_pump(relay_pin, "off")
                    response = {"status": "success", "message": "Pump turned OFF"}
                elif command.get("command") == "get_status":
                    temperature = read_temperature()
                    response = get_status(relay_pin, temperature)
                else:
                    response = {"status": "error", "message": "Invalid command"}

                conn.sendall(json.dumps(response).encode())
            except json.JSONDecodeError:
                log_error("Received malformed JSON from client.")
                conn.sendall(json.dumps({"status": "error", "message": "Invalid JSON"}).encode())
            except Exception as e:
                log_error(f"Error handling client: {e}")
                conn.sendall(json.dumps({"status": "error", "message": "Internal server error"}).encode())

    except Exception as e:
        log_error(f"Error handling client {addr}: {e}")
    finally:
        conn.close()
        print(f"Connection with {addr} closed.")

def main():
    """Main function to run the hydroponics controller."""
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=RELAY_PIN, help="GPIO pin for the relay")
    parser.add_argument("--dht_pin", type=int, default=DHT_PIN, help="GPIO pin for the DHT sensor")
    parser.add_argument("--port", type=int, default=12345, help="Port to listen on")
    parser.add_argument("--authorized_ip", type=str, default=AUTHORIZED_IP, help="Authorized IP address")
    parser.add_argument("--log_file", type=str, default=LOG_FILE, help="Path to the log file")

    args = parser.parse_args()

    try:
        setup_gpio(args.relay_pin, args.dht_pin)
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)  # Allow reuse of the address
        server_socket.bind(("", args.port))
        server_socket.listen(1)
        print(f"Listening on port {args.port}")

        while True:
            conn, addr = server_socket.accept()
            handle_client(conn, addr, args.relay_pin, args.dht_pin, args.port, args.authorized_ip)
    except KeyboardInterrupt:
        print("Shutting down...")
    except Exception as e:
        log_error(f"An unexpected error occurred: {e}")
    finally:
        if 'server_socket' in locals():
            server_socket.close()
        GPIO.cleanup()  # Clean up GPIO on exit
        print("Hydroponics controller stopped.")

if __name__ == "__main__":
    main()

