import serial
import time
import csv
import sys

# Configuration constants
UART_PORT = "/dev/ttyACM0"
BAUD_RATE = 115200
CSV_FILE = "temperature_log.csv"
CSV_HEADER = "timestamp,Celsius,Fahrenheit"

def initialize_uart(port, baud):
    """Initializes the UART connection."""
    try:
        uart = serial.Serial(port, baud, timeout=1)
        return uart
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        sys.exit(1)

def read_temperature(uart):
    """Reads temperature data from the UART port."""
    try:
        line = uart.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Malformed data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading from UART: {e}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return celsius * 9/5 + 32

def write_to_csv(filename, row):
    """Appends a row to the CSV file."""
    try:
        with open(filename, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            if csvfile.tell() == 0:  # Check if the file is empty to write the header
                writer.writerow(CSV_HEADER)
            writer.writerow(row)
    except IOError as e:
        print(f"Error writing to CSV file: {e}")

def main():
    """Main function to read temperature data and log it to a CSV file."""
    uart_connection = initialize_uart(UART_PORT, BAUD_RATE)

    try:
        while True:
            temperature_celsius = read_temperature(uart_connection)
            if temperature_celsius is not None:
                temperature_fahrenheit = convert_to_fahrenheit(temperature_celsius)
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                log_entry = [timestamp, temperature_celsius, temperature_fahrenheit]
                write_to_csv(CSV_FILE, log_entry)
                print(f"Logged: {log_entry}")
            time.sleep(1)  # Pacing to avoid busy-waiting

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        if uart_connection.is_open:
            uart_connection.close()
            print("UART connection closed.")

if __name__ == "__main__":
    main()

