import serial
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for serial port and sensor thresholds
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def read_temperature_humidity(serial_connection):
    """Reads temperature and humidity data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                temperature, humidity = line.split(',')
                return float(temperature), float(humidity)
            except ValueError:
                logging.error(f"Malformed data received: {line}")
                return None, None
        else:
            return None, None
    except serial.SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return None, None
    except Exception as e:
        logging.error(f"Unexpected error reading sensor data: {e}")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature or humidity exceeds predefined thresholds."""
    if temperature is not None and humidity is not None:
        if temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
            logging.warning(f"Threshold exceeded: Temperature={temperature}°C, Humidity={humidity}%")

def main():
    """Main function to read sensor data and check thresholds."""
    serial_connection = None
    try:
        # Establish serial connection
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        logging.info(f"Connected to serial port {SERIAL_PORT}")

        while True:
            temperature, humidity = read_temperature_humidity(serial_connection)

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature}°C, Humidity: {humidity}%")
                check_thresholds(temperature, humidity)

            time.sleep(1)

    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure serial port is closed on exit
        if serial_connection is not None and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial port closed.")

if __name__ == "__main__":
    main()

