DEVICE_ADDRESS = 0x20
PI_MODEL = 1
LED_PIN = 0
SWITCH_PIN = 7
POLL_INTERVAL = 0.1

def initialize_gpio(switch_pin, led_pin):
    """Initializes the MCP23017 chip for switch input and LED output."""
    try:
        gpio_chip = GPIO_CHIP(DEVICE_ADDRESS, PI_MODEL)
        gpio_chip.setup(switch_pin, 'in', 'pull_up_down'=1)
        gpio_chip.setup(led_pin, 'out')
        return gpio_chip
    except MCP23017Error as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def read_switch_state(gpio_chip, switch_pin):
    """Reads the state of the mechanical switch."""
    try:
        return gpio_chip.input(switch_pin)
    except MCP23017Error as e:
        print(f"Error reading switch state: {e}")
        return None  # Or handle the error differently, e.g., retry

def control_led(gpio_chip, led_pin, state):
    """Controls the LED state based on the provided state (True/False)."""
    try:
        gpio_chip.output(led_pin, state)
    except MCP23017Error as e:
        print(f"Error controlling LED: {e}")


def main():
    """Main function to monitor the switch and control the LED."""
    gpio_chip = initialize_gpio(SWITCH_PIN, LED_PIN)

    try:
        while True:
            switch_state = read_switch_state(gpio_chip, SWITCH_PIN)
            if switch_state is not None:
                led_state = False if switch_state else True
                control_led(gpio_chip, LED_PIN, led_state)

                print(f"Led {'ON' if led_state else 'OFF'}") # Print LED status

            time.sleep(POLL_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program.")
        control_led(gpio_chip, LED_PIN, False) # Turn off LED on exit
        sys.exit(0)


if __name__ == "__main__":
    main()

