import RPi.GPIO as GPIO
import time

# BCM pin connected to the magnetic reed switch
REED_PIN = 22

def setup_reed_switch(pin):
    """Configure the reed switch pin as a digital input with pull-up."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

def read_reed_switch(pin):
    """Read the current state of the reed switch."""
    return GPIO.input(pin)

def describe_state(state_value):
    """Return a human readable description of the switch state."""
    return "Door Closed" if state_value == GPIO.LOW else "Door Open"

def main():
    """Continuously poll the reed switch and report door status."""
    setup_reed_switch(REED_PIN)
    try:
        while True:
            switch_state = read_reed_switch(REED_PIN)
            door_status = describe_state(switch_state)
            print(door_status)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping door monitor")
    except Exception as monitor_error:
        print("Monitor error:", monitor_error)
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

