I2C_SDA_PIN = 2

# Define moisture threshold
MOISTURE_THRESHOLD = 300

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_soil_sensor(i2c_bus):
    """Initialize the soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus)
    except Exception as e:
        print(f"Error initializing soil moisture sensor: {e}")
        return None

def initialize_gpio():
    """Initialize GPIO pins."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(WATER_PUMP_PIN, GPIO.OUT)
    GPIO.output(WATER_PUMP_PIN, GPIO.LOW)  # Ensure pump is off initially

def read_moisture_level(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading moisture level: {e}")
        return None

def control_water_pump(moisture_level, pump_pin):
    """Control the water pump based on the moisture level."""
    if moisture_level is not None:
        if moisture_level < MOISTURE_THRESHOLD:
            GPIO.output(pump_pin, GPIO.HIGH)
            print("Activating water pump: Moisture level too low.")
        else:
            GPIO.output(pump_pin, GPIO.LOW)
            print("Deactivating water pump: Moisture level sufficient.")

def main():
    """Main function to read soil moisture and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
