            time.sleep(10)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.output(WATER_PUMP_PIN, GPIO.LOW)  # Ensure pump is off on exit
        GPIO.cleanup()
        print("GPIO cleaned up.")

if __name__ == "__main__":
    main()

