import RPi.GPIO as GPIO
import time
import signal
import sys

# Define sensor pins using BCM numbering
SENSOR_PINS = {
    1: 17,
    2: 27,
    3: 22,
}

# Global flag to control the main loop
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C and other signals for graceful shutdown."""
    global running
    print("Exiting gracefully...")
    running = False

def initialize_gpio():
    """Initializes GPIO pins for the sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for sensor_id, pin in SENSOR_PINS.items():
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
            print(f"Sensor {sensor_id}: GPIO {pin} initialized.")
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)

def read_sensor_state(pin):
    """Reads the state of a sensor."""
    try:
        return GPIO.input(pin)
    except Exception as e:
        print(f"Error reading sensor {pin}: {e}")
        return None

def main():
    """Main function to continuously monitor sensor states."""
    global running

    # Register signal handler for graceful shutdown
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    initialize_gpio()

    print("Starting sensor monitoring...")

    try:
        while running:
            for sensor_id, pin in SENSOR_PINS.items():
                state = read_sensor_state(pin)
                if state is not None:
                    print(f"Sensor {sensor_id}: {'HIGH' if state else 'LOW'}")
            time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

