import RPi.GPIO as GPIO
import time

# Define GPIO pins using BCM numbering
BUTTON_PIN = 17
LED_PIN = 27

# Debounce time in seconds
DEBOUNCE_TIME = 0.02

def setup_gpio():
    """Initialize GPIO settings."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(BUTTON_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(LED_PIN, GPIO.OUT)
        GPIO.output(LED_PIN, GPIO.LOW)  # Ensure LED is off initially
    except Exception as e:
        print(f"GPIO setup error: {e}")
        return False  # Indicate setup failure
    return True  # Indicate success

def button_pressed_callback(channel):
    """Callback function for button press event."""
    try:
        GPIO.output(LED_PIN, GPIO.HIGH)  # Turn LED on
        time.sleep(0.5)  # Keep LED on for 0.5 seconds
        GPIO.output(LED_PIN, GPIO.LOW)   # Turn LED off
    except Exception as e:
        print(f"Event handling error: {e}")

def main_loop():
    """Main program loop."""
    try:
        while True:
            time.sleep(0.1)  # Check for button press every 0.1 seconds
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    if setup_gpio():
        # Set up event detection with debounce
        GPIO.add_event_detect(BUTTON_PIN, GPIO.RISING, callback=button_pressed_callback, bouncetime=int(DEBOUNCE_TIME * 1000))
        main_loop()
    else:
        print("GPIO setup failed. Exiting.")

