import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO

# Define constants
I2C_BUS = 1
TSL_INTEGRATION_TIME = 0.402  # seconds
PWM_FREQUENCY = 1000  # Hz
LED_GPIO_PIN = 18
READ_INTERVAL_SECONDS = 1.0

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus)
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        return None

def initialize_pwm(led_pin):
    """Initialize the PWM on the LED pin."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(led_pin, GPIO.OUT)
        pwm_led = GPIO.PWM(led_pin, PWM_FREQUENCY)
        pwm_led.start(0)
        return pwm_led
    except Exception as e:
        print(f"Error initializing PWM: {e}")
        return None

def read_light_level(sensor):
    """Read the ambient light level from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}")
        return None

def map_light_to_brightness(light_level, min_level=0, max_level=10000):
    """Map the light level to a brightness percentage."""
    if light_level is None:
        return 0
    return int((light_level / max_level) * 100)

def set_led_brightness(pwm_led, brightness):
    """Set the LED brightness using PWM."""
    try:
        pwm_led.ChangeDutyCycle(brightness)
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to control LED brightness based on ambient light."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        i2c_bus.deinit()
        return

    pwm_led = initialize_pwm(LED_GPIO_PIN)
    if pwm_led is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            light_level = read_light_level(light_sensor)
            if light_level is not None:
                brightness = map_light_to_brightness(light_level)
                set_led_brightness(pwm_led, brightness)
                print(f"Ambient Light: {light_level:.2f} lux, LED Brightness: {brightness}%")
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Cleanup resources
        pwm_led.stop()
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C cleaned up.")

if __name__ == "__main__":
    main()

