import RPi.GPIO as GPIO
import time

# Define GPIO pins for the infrared sensors
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Setup GPIO numbering mode
GPIO.setmode(GPIO.BCM)

# Configure GPIO pins as inputs
try:
    GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN)
    GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN)
except Exception as e:
    print(f"Error setting up GPIO: {e}")
    exit()


def read_sensor(pin):
    """Read the digital value from a sensor pin."""
    return GPIO.input(pin)


def collect_sensors():
    """Read both sensors and return their values."""
    left_reading = read_sensor(LEFT_SENSOR_PIN)
    right_reading = read_sensor(RIGHT_SENSOR_PIN)
    return left_reading, right_reading


def describe_direction(left_value, right_value):
    """Translate sensor readings into a driving direction."""
    if left_value == 0 and right_value == 0:
        return "forward"
    elif left_value == 0:
        return "turn_left"
    elif right_value == 0:
        return "turn_right"
    else:
        return "search"


def main():
    """Main program loop for the line follower."""
    sensor_samples = 0
    try:
        while sensor_samples < 10:
            left_reading, right_reading = collect_sensors()
            print("Left Sensor: %d, Right Sensor: %d" % (left_reading, right_reading))
            direction = describe_direction(left_reading, right_reading)
            sensor_samples += 1
            time.sleep(0.5)
