    try:
        sensor = adafruit_tsl2561.TSL2561(i2c_bus, address=I2C_ADDRESS)
        sensor.auto_gain = adafruit_tsl2561.AUTOGAIN_ENABLE
        return sensor
    except Exception as e:
        print(f"Error initializing light sensor: {e}")
        return None

def initialize_gpio(led_pin, pwm_frequency):
    """Initialize GPIO for LED control."""
    try:
