import RPi.GPIO as GPIO
import time
import logging
import json
import socket
import threading
import signal
import sys

# Configuration
CONFIG = {
    "led1_red": 17, "led1_green": 18, "led1_blue": 27, "led2_red": 22, "led2_green": 23, "led2_blue": 24, "led3_red": 5, "led3_green": 6, "led3_blue": 13,
    "cpu_usage_threshold": 66, "memory_usage_threshold": 66, "disk_io_threshold": 66,
    "socket_address": ("192.168.1.100", 5000),
    "log_file": "notification_light.log",
    "log_level": logging.INFO,
    "pwm_frequency": 1000,
    "backoff_delay": 1,
    "max_backoff_delay": 60
}

# Global variables
stop_event = threading.Event()
pwm_objects = {}
data_lock = threading.Lock()
data_queue = []
socket = None
logger = None

# Custom Exception Classes
class GPIOInitializationError(Exception):
    pass

class SocketConnectionError(Exception):
    pass

class JSONDecodeError(Exception):
    pass

class DataRangeError(Exception):
    pass

# Logging Configuration
logging.basicConfig(filename=CONFIG["log_file"], level=CONFIG["log_level"],
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Signal Handler for graceful shutdown
def signal_handler(sig, frame):
    logger.info("Shutting down...")
    stop_event.set()
    for led, pwm in pwm_objects.items():
        pwm.stop()
        GPIO.setup(led, GPIO.IN)  # Set to input to prevent issues
    GPIO.cleanup()
    if socket:
        try:
            socket.close()
        except:
            pass
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Function to initialize GPIO pins
def initialize_gpio():
    try:
        GPIO.setmode(GPIO.BCM)
        for led, pins in CONFIG.items():
            GPIO.setup(pins["red"], GPIO.OUT)
            GPIO.setup(pins["green"], GPIO.OUT)
            GPIO.setup(pins["blue"], GPIO.OUT)
            GPIO.output(pins["red"], GPIO.LOW)
            GPIO.output(pins["green"], GPIO.LOW)
            GPIO.output(pins["blue"], GPIO.LOW)
            global pwm_objects
            pwm_objects[led] = GPIO.PWM(pins["red"], CONFIG["pwm_frequency"])
            pwm_objects[led].start(0)
    except Exception as e:
        logger.error(f"GPIO initialization failed: {e}")
        raise GPIOInitializationError(f"GPIO initialization failed: {e}")

# Function to set LED color using PWM
def set_led_color(led, red, green, blue):
    try:
        pwm_objects[led].ChangeDutyCycle(red)
        pwm_objects[led].ChangeDutyCycle(green)
        pwm_objects[led].ChangeDutyCycle(blue)
    except Exception as e:
        logger.error(f"Error setting LED color for {led}: {e}")

# Function to parse JSON data
def parse_json_data(data):
    try:
        return json.loads(data.decode('utf-8'))
    except json.JSONDecodeError as e:
        logger.error(f"JSON decode error: {e}, Data: {data}")
        raise JSONDecodeError(f"JSON decode error: {e}, Data: {data}")

# Function to map data to color range
def map_data_to_color_range(cpu_usage, memory_usage, disk_io, led):
    if cpu_usage > CONFIG["cpu_usage_threshold"]:
        return (0, 1, 0)  # Red
    elif memory_usage > CONFIG["memory_usage_threshold"]:
        return (1, 0, 0)  # Red
    elif disk_io > CONFIG["disk_io_threshold"]:
        return (0, 1, 0)  # Red
    elif 66 <= cpu_usage <= 100 or 66 <= memory_usage <= 100 or 66 <= disk_io <= 100:
        return (1, 0, 0)  # Orange
    elif 33 <= cpu_usage <= 65 or 33 <= memory_usage <= 65 or 33 <= disk_io <= 65:
        return (1, 1, 0)  # Yellow
    elif 0 <= cpu_usage <= 32 or 0 <= memory_usage <= 32 or 0 <= disk_io <= 32:
        return (0, 1, 1)  # Blue
    else:
        return (0, 0, 1)  # Green

# Function to add data to the queue
def add_data_to_queue(data):
    global data_queue
    with data_lock:
        data_queue.append(data)

# Function to process data from the queue
def process_data_from_queue():
    global data_queue
    while data_queue:
        data = data_queue.pop(0)
        try:
            cpu_usage = parse_json_data(data)
            if 0 <= cpu_usage <= 100:
                set_led_color("CPU", cpu_usage, 100 - cpu_usage, 0)
            else:
                logger.warning(f"Invalid CPU usage value: {cpu_usage}")
        except JSONDecodeError as e:
            logger.error(f"JSON decode error: {e}, Data: {data}")
        except Exception as e:
            logger.error(f"Error processing CPU data: {e}, Data: {data}")
        try:
            memory_usage = parse_json_data(data)
            if 0 <= memory_usage <= 100:
                set_led_color("Memory", 100 - memory_usage, memory_usage, 0)
            else:
                logger.warning(f"Invalid Memory usage value: {memory_usage}")
        except JSONDecodeError as e:
            logger.error(f"JSON decode error: {e}, Data: {data}")
        except Exception as e:
            logger.error(f"Error processing Memory data: {e}, Data: {data}")
        try:
            disk_io = parse_json_data(data)
            if 0 <= disk_io <= 100:
                set_led_color("Disk I/O", 0, disk_io, 0)
            else:
                logger.warning(f"Invalid Disk I/O value: {disk_io}")
        except JSONDecodeError as e:
            logger.error(f"JSON decode error: {e}, Data: {data}")
        except Exception as e:
            logger.error(f"Error processing Disk I/O data: {e}, Data: {data}")

# Function to handle incoming data
def handle_incoming_data():
    global data_queue, stop_event
    while not stop_event.is_set():
        try:
            data = socket.recv(1024)
            if data:
                add_data_to_queue(data)
        except socket.error as e:
            logger.error(f"Socket error: {e}")
            if socket:
                try:
                    socket.close()
                except:
                    pass
            time.sleep(5)  # Exponential backoff
            socket = None # Reset socket to force reconnection
            initialize_gpio() # Re-initialize GPIO on connection loss
        except Exception as e:
            logger.error(f"Error in handle_incoming_data: {e}")
            time.sleep(5)  # Exponential backoff
            socket = None # Reset socket to force reconnection
            initialize_gpio() # Re-initialize GPIO on connection loss

# Function to connect to the remote server
def connect_to_server():
    global socket
    try:
        socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        socket.settimeout(10)  # Set a timeout for the connection attempt
        socket.connect(CONFIG["socket_address"])
        logger.info(f"Connected to {CONFIG['socket_address']}")
    except socket.error as e:
        logger.error(f"Failed to connect to {CONFIG['socket_address']}: {e}")
        raise SocketConnectionError(f"Failed to connect to {CONFIG['socket_address']}: {e}")

# Function to reconnect to the server with exponential backoff
def reconnect_to_server():
    global socket
    while not stop_event.is_set():
        try:
            connect_to_server()
            break  # Exit the loop if connection is successful
        except SocketConnectionError:
            logger.warning(f"Reconnecting to {CONFIG['socket_address']} in {CONFIG['backoff_delay']} seconds...")
            time.sleep(CONFIG["backoff_delay"])
            CONFIG["backoff_delay"] = min(CONFIG["backoff_delay"] * 2, CONFIG["max_backoff_delay"])  # Exponential backoff
            if CONFIG["backoff_delay"] > CONFIG["max_backoff_delay"]:
                logger.warning(f"Maximum backoff delay reached. Exiting reconnection loop.")
                break

# Main function
def main():
    global logger
    try:
        initialize_gpio()
        connect_to_server()
        process_data_from_queue() # Process any data already in the queue
        reconnect_to_server() # Attempt to reconnect if connection is lost
        while not stop_event.is_set():
            add_data_to_queue(socket.recv(1024)) # Add received data to the queue
            time.sleep(0.1) # Reduce CPU usage
    except GPIOInitializationError:
        logger.critical("GPIO initialization failed. Exiting.")
    except SocketConnectionError:
        logger.critical("Failed to connect to server. Exiting.")
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        if socket:
            try:
                socket.close()
            except:
                pass
        GPIO.cleanup()
        logger.info("Program finished.")

if __name__ == "__main__":
    main()

