#!/usr/bin/env python3

import time
import atexit
import logging
import signal

try:
    from Adafruit_MotorHAT import Adafruit_MotorHAT as MotorHAT
except ImportError:
    logging.error("Adafruit_MotorHAT library not found. Please install it.")
    raise

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
PWM_FREQUENCY = 60  # Hz
MOTOR_NUMBERS = range(1, 5)

# Global variable for the motor hat instance
motor_hat = None

def initialize_motor_hat():
    """Initializes the Adafruit Motor HAT and sets up PWM frequency."""
    global motor_hat
    try:
        motor_hat = MotorHAT()
        motor_hat.setPWMFreq(PWM_FREQUENCY)
        logging.info("Motor HAT initialized successfully.")
    except Exception as e:
        logging.error(f"Failed to initialize Motor HAT: {e}")
        raise

def cleanup_motors():
    """Stops all motors and releases resources."""
    logging.info("Cleaning up motors...")
    if motor_hat is not None:
        for motor_number in MOTOR_NUMBERS:
            try:
                motor_hat.getMotor(motor_number).run(MotorHAT.RELEASE)
                logging.debug(f"Motor {motor_number} released.")
