import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
PUMP_GPIO_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_soil_sensor(i2c_bus):
    """Initialize the soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x68)
    except Exception as e:
        print(f"Error initializing soil sensor: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize GPIO for pump control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pump_pin, GPIO.OUT)
        GPIO.output(pump_pin, GPIO.LOW)  # Ensure pump is initially off
    except Exception as e:
        print(f"Error initializing GPIO: {e}")

def read_soil_moisture(sensor):
    """Read soil moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_pump(pump_pin, moisture_level, dry_threshold):
    """Control the water pump based on soil moisture."""
    try:
        if moisture_level is not None and moisture_level < dry_threshold:
            GPIO.output(pump_pin, GPIO.HIGH)  # Turn pump ON
            pump_status = "ON"
        else:
            GPIO.output(pump_pin, GPIO.LOW)  # Turn pump OFF
            pump_status = "OFF"
        return pump_status
    except Exception as e:
        print(f"Error controlling pump: {e}")
        return "ERROR"

def main():
    """Main function to monitor soil moisture and control the pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    soil_sensor = initialize_soil_sensor(i2c_bus)
    if soil_sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture = read_soil_moisture(soil_sensor)
            if moisture is not None:
                pump_state = control_pump(PUMP_GPIO_PIN, moisture, DRY_SOIL_THRESHOLD)
                print(f"Soil Moisture: {moisture}, Pump {pump_state}")
            time.sleep(READ_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        # Ensure pump is off and GPIO resources are released
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

