#!/usr/bin/env python3

"""
Raspberry Pi UPS Plus Demo Code (Intermediate - Functional)

This script demonstrates the UPS Plus module's functionalities using a functional programming style.
It reads various parameters such as voltage, current, temperature, and power status
from both the Raspberry Pi side and the battery side. It also showcases how to set
certain parameters like protection voltage, sampling period, and shutdown countdown.

Advanced users can customize and develop this code to meet their specific needs.
"""

import time
import smbus2
from ina219 import INA219, DeviceRangeError
from typing import Optional, Tuple, List
from functools import partial

# Constants
I2C_BUS = 1  # I2C bus number
SUPPLY_VOLTAGE = 5.0  # Fixed 5V supply for the sensors
SHUNT_RESISTOR = 0.00725  # Shunt resistor value in ohms
BATTERY_SHUNT_RESISTOR = 0.005  # Shunt resistor value for the battery
PROTECTION_VOLTAGE = 3.50  # Battery protection voltage in volts
SAMPLING_PERIOD = 5  # Sampling period in seconds
SUPPLY_INA219 = INA219(SUPPLY_VOLTAGE, shunt_resistor=SHUNT_RESISTOR)
BATTERY_INA219 = INA219(SUPPLY_VOLTAGE, shunt_resistor=BATTERY_SHUNT_RESISTOR)
UPS_PLUS_ADDRESS = 0x40 # Default address of the UPS Plus module.
LOG_LEVEL = 1  # Log level: 0 for error-only, 1 for info & error, 2 for verbose
CALIBRATION_VALUE = 4096 # Fixed calibration value for INA219

# Global Variables
bus = None  # I2C bus object
running = True # Flag to control the main loop


def safe_init_bus() -> Optional[smbus2.SMBus]:
    """Initializes the I2C bus with error handling."""
    try:
        bus = smbus2.SMBus(I2C_BUS)
        return bus
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def read_rpi_current() -> Optional[float]:
    """Reads the Raspberry Pi's current consumption."""
    try:
        current = SUPPLY_INA219.current
        if current is not None:
            return current
        else:
            return None
    except Exception as e:
        print(f"Error reading RPi current: {e}")
        return None


def read_battery_current() -> Optional[float]:
    """Reads the battery's current consumption."""
    try:
        current = BATTERY_INA219.current
        if current is not None:
            return current
        else:
            return None
    except Exception as e:
        print(f"Error reading battery current: {e}")
        return None


def read_supply_voltage() -> Optional[float]:
    """Reads the Raspberry Pi's supply voltage."""
    try:
        voltage = SUPPLY_INA219.voltage
        if voltage is not None:
            return voltage
        else:
            return None
    except Exception as e:
        print(f"Error reading supply voltage: {e}")
        return None


def read_battery_voltage() -> Optional[float]:
    """Reads the battery's voltage."""
    try:
        voltage = BATTERY_INA219.voltage
        if voltage is not None:
            return voltage
        else:
            return None
    except Exception as e:
        print(f"Error reading battery voltage: {e}")
        return None


def read_temperature() -> Optional[float]:
    """Reads the battery's temperature."""
    try:
        temperature = BATTERY_INA219.temperature
        if temperature is not None:
            return temperature
        else:
            return None
    except Exception as e:
        print(f"Error reading battery temperature: {e}")
        return None


def read_power_status() -> Optional[str]:
    """Reads the power status from the UPS Plus module."""
    try:
        power_status = UPS_PLUS_ADDRESS.readU2c(0x00)
        if power_status is not None:
            return "ON" if power_status == 1 else "OFF"
        else:
            return None
    except Exception as e:
        print(f"Error reading power status: {e}")
        return None


def read_shutdown_countdown() -> Optional[int]:
    """Reads the shutdown countdown from the UPS Plus module."""
    try:
        shutdown_countdown = UPS_PLUS_ADDRESS.readU2c(0x02)
        if shutdown_countdown is not None:
            return shutdown_countdown
        else:
            return None
    except Exception as e:
        print(f"Error reading shutdown countdown: {e}")
        return None


def read_all_data() -> List[Optional[object]]:
    """Reads all sensor data as a list of Optional objects."""
    data = []
    data.append(read_rpi_current())
    data.append(read_battery_current())
    data.append(read_supply_voltage())
    data.append(read_battery_voltage())
    data.append(read_temperature())
    data.append(read_power_status())
    data.append(read_shutdown_countdown())
    return data


def process_data(data: List[Optional[object]]) -> List[float]:
    """Processes the sensor data, handling None values."""
    processed_data = []
    for i, value in enumerate(data):
        if value is not None:
            processed_data.append(value)
        else:
            processed_data.append(0.0 if isinstance(value, (int, float)) else None) # Ensure consistent type
    return processed_data


def log_data(log_level: int, data: List[object]) -> None:
    """Logs the sensor data to the console."""
    if log_level > 0:
        timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
        print(timestamp)


def format_log_message(rpi_current: Optional[float], battery_current: Optional[float],
                       rpi_voltage: Optional[float], battery_voltage: Optional[float],
                       battery_temperature: Optional[float], power_status: Optional[str],
