# I2C device helper for a Raspberry Pi, keeping the API clean and safe
import smbus2
import contextlib

def _raise_i2c_error(inner_exception):
    """Raise a RuntimeError when I2C operations fail."""
    # Convert specific exceptions to a generic RuntimeError for clarity
    raise RuntimeError("I2C operation failed: %s" % str(inner_exception))

def _open_bus(bus_number=1):
    """Open the I2C bus and return a context manager."""
    try:
        return contextlib.closing(smbus2.SMBus(bus_number))
    except Exception as e:
        # Handle any error opening the I2C bus
        raise RuntimeError("Could not open I2C bus: %s" % str(e))

class I2CDevice:
    """Generic I2C device helper for Raspberry Pi."""

    def __init__(self, address, bus_number=1):
        """Open the I2C bus and probe the device at the given address."""
        self.address = address
        self.bus = _open_bus(bus_number)
        try:
            # Verify the device acknowledges on the bus
            self.bus.read_byte(self.address)
        except OSError:
            # Close the bus if the device is not present
            self.bus = None
            raise RuntimeError("I2C device not found at address %s" % self.address)
        except Exception as inner_exception:
            _raise_i2c_error(inner_exception)

    def write_byte(self, register, value):
        """Write a single byte to the given register."""
        if self.bus is None:
            raise RuntimeError("I2C bus not open")
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as outer_exception:
            _raise_i2c_error(outer_exception)

    def read_byte(self, register):
        """Read a single byte from the given register."""
        if self.bus is None:
            raise RuntimeError("I2C bus not open")
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as outer_exception:
            _raise_i2c_error(outer_exception)

    def close(self):
        """Close the underlying I2C bus."""
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception as e:
                print("Error closing I2C bus:", e)


# Example usage (replace with your actual device address and register)
DEVICE_ADDRESS = 0x40
CONTROL_REGISTER = 0x00
try:
    i2c_device = I2CDevice(DEVICE_ADDRESS)
    i2c_device.write_byte(CONTROL_REGISTER, 0x01)  # Set control bit
    value = i2c_device.read_byte(CONTROL_REGISTER)
    print("Control register value:", value)
except RuntimeError as error:
    print("I2C error:", error)

