import smbus
import time
import datetime
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DS1338_I2C_ADDR = 0x68
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07
YEAR_2000 = 0x00  # Control register bit for the year 2000

# Initialize the I2C bus and check for the DS1338
try:
    bus = smbus.SMBus(1)
    bus.read_byte_data(DS1338_I2C_ADDR, REG_SECONDS)  # Quick check
    logger.info("DS1338 RTC found.")
except FileNotFoundError:
    logger.error("I2C bus not found. Check your Raspberry Pi configuration.")
    sys.exit(1)
except Exception as e:
    logger.error(f"Error initializing I2C: {e}")
    sys.exit(1)

# Global variable to track running state for graceful shutdown
running = True

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    global running
    logger.info("Shutting down...")
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def bcd_to_int(bcd):
    """Converts a BCD value to an integer."""
    try:
        return (bcd >> 4) * 10 + (bcd & 0x0F)
    except TypeError:
        logger.error(f"Invalid BCD value: {bcd}")
        return None

def int_to_bcd(int_value):
    """Converts an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (int_value // 10 << 4) | (int_value % 10)

def read_register(bus, register):
    """Reads a byte from the specified register."""
    try:
        return bus.read_byte_data(DS1338_I2C_ADDR, register)
    except OSError as e:
        logger.error(f"I2C read error: {e}")
        return None

def write_register(bus, register, value):
    """Writes a byte to the specified register."""
    try:
        bus.write_byte_data(DS1338_I2C_ADDR, register, value)
    except OSError as e:
        logger.error(f"I2C write error: {e}")
        return False
    return True

def read_time_register(bus, register):
    """Reads and converts a time register value (seconds, minutes, etc.)."""
    value = read_register(bus, register)
    if value is None:
        return None

    if register == REG_SECONDS:
        return bcd_to_int(value)
    elif register == REG_MINUTES:
        return bcd_to_int(value)
    elif register == REG_HOURS:
        value = bcd_to_int(value)
        if value is None:
            return None
        if value >= 24:
            value -= 24
        return value
    elif register == REG_DAY:
        return bcd_to_int(value)
    elif register == REG_DATE:
        return bcd_to_int(value)
    elif register == REG_MONTH:
        return bcd_to_int(value)
    elif register == REG_YEAR:
        return read_year(bus, value)
    else:
        logger.warning(f"Unknown register: 0x{register:02X}")
        return None

def read_year(bus, value):
    """Reads and converts the year value, handling century bits."""
    year = bcd_to_int(value)
    if year is None:
        return None

    if year >= 50:
        return year - 100
    else:
        return year + 2000

def write_time_register(bus, register, value):
    """Writes a time register value (seconds, minutes, etc.)."""
    if value is None:
        return

    if register == REG_SECONDS:
        value = int_to_bcd(value)
    elif register == REG_MINUTES:
        value = int_to_bcd(value)
    elif register == REG_HOURS:
        value = int_to_bcd(value)
        if value is None:
            return
        if value >= 24:
            value -= 24
    elif register == REG_DAY:
        value = int_to_bcd(value)
    elif register == REG_DATE:
        value = int_to_bcd(value)
    elif register == REG_MONTH:
        value = int_to_bcd(value)
    elif register == REG_YEAR:
        value = int_to_bcd(value)
    write_register(bus, register, value)

def read_all(bus):
    """Reads all time registers and returns them as a tuple."""
    try:
        seconds = read_time_register(bus, REG_SECONDS)
        minutes = read_time_register(bus, REG_MINUTES)
        hours = read_time_register(bus, REG_HOURS)
        day = read_time_register(bus, REG_DAY)
        date = read_time_register(bus, REG_DATE)
        month = read_time_register(bus, REG_MONTH)
        year = read_time_register(bus, REG_YEAR)
        return seconds, minutes, hours, day, date, month, year
    except Exception as e:
        logger.error(f"Error reading all registers: {e}")
        return None

def write_all(bus, seconds, minutes, hours, day, date, month, year):
    """Writes all time registers."""
    try:
        write_register(bus, REG_SECONDS, seconds)
        write_register(bus, REG_MINUTES, minutes)
        write_register(bus, REG_HOURS, hours)
        write_register(bus, REG_DAY, day)
        write_register(bus, REG_DATE, date)
        write_register(bus, REG_MONTH, month)
        write_register(bus, REG_YEAR, year)
    except Exception as e:
        logger.error(f"Error writing all registers: {e}")

def read_datetime(bus):
    """Reads the date and time and returns a datetime object."""
    try:
        seconds, minutes, hours, day, date, month, year = read_all(bus)
        if seconds is None or minutes is None or hours is None or day is None or date is None or month is None or year is None:
            logger.error("Error reading datetime.")
            return None

        return datetime.datetime(year, month, date, hours, minutes, seconds)
    except Exception as e:
        logger.error(f"Error reading datetime: {e}")
        return None

def write_datetime(bus, dt):
    """Writes date and time from a datetime object."""
    try:
        year = dt.year
        month = dt.month
        date = dt.day
        hours = dt.hour
        minutes = dt.minute
        seconds = dt.second

        write_all(bus, seconds, minutes, hours, date, month, year)
    except Exception as e:
        logger.error(f"Error writing datetime: {e}")

def validate_datetime(dt):
    """Validates a datetime object and returns it with default values if invalid."""
    if dt is None:
        return None

    try:
        if not 1 <= dt.hour <= 24:
            raise ValueError("Hour must be between 1 and 24.")
        if not 0 <= dt.minute <= 59:
            raise ValueError("Minute must be between 0 and 59.")
        if not 0 <= dt.second <= 59:
            raise ValueError("Second must be between 0 and 59.")
        if not 1 <= dt.day <= 31:
            raise ValueError("Day must be between 1 and 31.")
        if not 1 <= dt.month <= 12:
            raise ValueError("Month must be between 1 and 12.")
        if not 0 <= dt.year <= 9999:
            raise ValueError("Year must be between 0 and 9999.")

        return dt
    except ValueError as ve:
        logger.warning(f"Invalid datetime value: {ve}")
        return None

def main():
    """Main function to read and write date and time."""
    try:
        while running:
            try:
                dt = read_datetime(bus)
                if dt is not None:
                    validated_dt = validate_datetime(dt)
                    if validated_dt is not None:
                        logger.info(f"Date and time: {validated_dt}")
                else:
                    logger.warning("Could not read datetime.")
            except Exception as e:
                logger.error(f"Error in main loop: {e}")

            time.sleep(1)

    except Exception as e:
        logger.error(f"Unexpected error in main: {e}")
    finally:
        logger.info("Exiting program.")

if __name__ == "__main__":
    main()

