This module provides a robust and efficient driver for the DS1338 RTC chip.
"""

import smbus
from datetime import datetime
import contextlib

class DS1338Error(Exception):
    """Custom exception for DS1338 errors."""
    pass

def _bcd_to_int(bcd_value):
    """Decode a 2x4bit BCD value to an integer."""
    try:
        return int(f"{bcd_value >> 4:01}{bcd_value & 0x0F:01}")
    except ValueError:
        raise DS1338Error("Invalid BCD value")


def _int_to_bcd(int_value):
    """Encode an integer to BCD format."""
    if not 0 <= int_value <= 99:
        raise DS1338Error("Integer value out of BCD range (0-99)")
    return (int_value // 10 << 4) | (int_value % 10)


def _year_2000(year):
    """Ensure year is within the range 2000-2099."""
    return 2000 + (year - 1) if year < 100 else year


def _twos_complement(value, bits=8):
    """Decode a 2's complement value."""
    if (value & (1 << (bits - 1))) != 0:
        value = value - (1 << bits)
    return value


def _seconds_to_twos_complement(seconds, bus):
    """Read and convert seconds value to 2's complement."""
    try:
        seconds_data = bus.read_byte_data(0x00, 0x00)
        return _twos_complement(seconds_data, 2)
    except IOError as e:
        raise DS1338Error(f"I/O error reading seconds: {e}")


