def _write_register(bus, address, register, value):
    """Write a single byte to the specified register."""
    try:
        bus.write_byte_data(address, register, value)
    except IOError as e:
        raise DS1338Error(f"I/O error writing to register {register}: {e}")


class DS1338:
    """DS1338 Real-Time Clock Driver."""

    # Register addresses for the DS1338
    REG_SECONDS = 0x00
    REG_MINUTES = 0x01
    REG_HOURS = 0x02
    REG_DAY = 0x03
    REG_DATE = 0x04
    REG_MONTH = 0x05
    REG_YEAR = 0x06

    def __init__(self, i2c_bus_number=1, device_address=0x68):
        """Initialize the DS1338 driver."""
        self.i2c_bus = smbus.SMBus(i2c_bus_number)
        self.device_address = device_address
        self._check_presence()

    def _check_presence(self):
        """Verify that the DS1338 device is present on the I2C bus."""
        try:
            self.i2c_bus.read_byte_data(self.device_address, 0x00)
        except IOError as e:
            raise DS1338Error(f"DS1338 not found at address 0x{self.device_address:02X}: {e}")

    def _open(self):
        """Open the I2C bus connection."""
        return self.i2c_bus

    def _close(self):
        """Close the I2C bus connection."""
        self.i2c_bus.close()

    def _setup_context_manager(self):
        """Context manager setup for resource management."""
        return contextlib.closing(self._open())

    def _cleanup(self):
        """Resource cleanup operation."""
        self._close()

    def read_all(self):
        """Read all time registers and return them as a tuple."""
        try:
            bus = self._setup_context_manager()
            seconds = _seconds_to_twos_complement(_read_register(bus, self.device_address, self.REG_SECONDS), bus)
            minutes = _minutes_to_twos_complement(_read_register(bus, self.device_address, self.REG_MINUTES), bus)
            hours = _hours_to_twos_complement(_read_register(bus, self.device_address, self.REG_HOURS), bus)
            day = _day_to_twos_complement(_read_register(bus, self.device_address, self.REG_DAY), bus)
            date = _date_to_twos_complement(_read_register(bus, self.device_address, self.REG_DATE), bus)
            month = _month_to_twos_complement(_read_register(bus, self.device_address, self.REG_MONTH), bus)
            year = _year_to_twos_complement(_read_register(bus, self.device_address, self.REG_YEAR), bus)

            return (
                _bcd_to_int(int(year)) if year >= 100 else int(year),
                _bcd_to_int(month),
                _bcd_to_int(date),
                _bcd_to_int(day),
                _bcd_to_int(hours),
                _bcd_to_int(minutes),
                _bcd_to_int(seconds),
            )

        except DS1338Error as e:
            raise  # Re-raise the exception after cleanup

    def read_datetime(self, timezone=timezone.utc):
        """Read the current time as a datetime object with timezone."""
        try:
            time_tuple = self.read_all()
            return datetime(2000 + time_tuple[0] - 1, 1, time_tuple[1], time_tuple[2], time_tuple[3],
                             time_tuple[4], time_tuple[5], microsecond=0).astimezone(timezone)
        except DS1338Error as e:
            raise  # Re-raise

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        """Write all time registers."""
        try:
            bus = self._setup_context_manager()
            _write_register(bus, self.device_address, self.REG_SECONDS, _bcd_to_int(seconds))
            _write_register(bus, self.device_address, self.REG_MINUTES, _bcd_to_int(minutes))
            _write_register(bus, self.device_address, self.REG_HOURS, _bcd_to_int(hours))
            _write_register(bus, self.device_address, self.REG_DAY, _bcd_to_int(day))
            _write_register(bus, self.device_address, self.REG_DATE, _bcd_to_int(date))
            _write_register(bus, self.device_address, self.REG_MONTH, _bcd_to_int(month))
            _write_register(bus, self.device_address, self.REG_YEAR, _bcd_to_int(year))

        except DS1338Error as e:
            raise  # Re-raise

    def write_datetime(self, dt):
        """Write a datetime object to the RTC."""
        try:
            self.write_all(
                _year_2000(dt.year), dt.month, dt.day, dt.isoweekday(),
                dt.hour, dt.minute, dt.second,
            )
        except DS1338Error as e:
            raise  # Re-raise

    def write_now(self):
        """Set the RTC to the current system time."""
        try:
            self.write_datetime(datetime.now())
        except DS1338Error as e:
            raise  # Re-raise


if __name__ == "__main__":
    driver = DS1338()
    try:
        driver.write_now()
        current_time = driver.read_datetime()
        print(f"Current time: {current_time}")
    except DS1338Error as e:
        print(f"DS1338 Error: {e}")
    finally:
        # Ensure the I2C bus is closed on exit
        driver._cleanup()

