def initialize_serial(port, baud, timeout):
    """Initializes and returns a serial connection."""
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_gpio(pin):
    """Initializes the GPIO pin for the alert LED."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def read_radiation_level(serial_connection):
    """Reads radiation level from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Invalid data received from sensor.")
        return None

def control_alert_led(pin, radiation_level, threshold):
    """Controls the alert LED based on the radiation level."""
    if radiation_level > threshold:
        GPIO.output(pin, GPIO.HIGH)
    else:
        GPIO.output(pin, GPIO.LOW)

def main():
    """Main function to read radiation data and control the alert LED."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        return

    initialize_gpio(GPIO_PIN)

    try:
        while True:
            radiation_level = read_radiation_level(serial_connection)
            if radiation_level is not None:
                print(f'Radiation Level: {radiation_level} µSv/h')
                control_alert_led(GPIO_PIN, radiation_level, ALERT_THRESHOLD)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Program terminated by user.")
    finally:
        serial_connection.close()
        GPIO.cleanup()
        print("Resources cleaned up.")

if __name__ == "__main__":
    main()

