                logging.error(f"Error disconnecting from serial port: {e}")

    def read_gps_data(self) -> Optional[GPSReadings]:
        """Read and parse GPS data from the serial port."""
        try:
            line = self.serial_connection.readline().decode('utf-8', errors='ignore').strip()
            if line.startswith('$GPGGA'):
                try:
                    msg = pynmea2.parse(line)
                    latitude = msg.latitude
                    longitude = msg.longitude
                    altitude = msg.altitude
                    satellites = msg.num_satellites
                    return GPSReadings(latitude, longitude, altitude, satellites)
                except pynmea2.ParseError as e:
                    logging.error(f"NMEA Parse Error: {e}")
                    return None
        except serial.SerialException as e:
